import { SkeletonData, Spine } from '@esotericsoftware/spine-pixi-v8';
import * as PIXI from 'pixi.js';

import { Slide } from './base-slide';

const TEXT_STYLE: Partial<PIXI.TextStyle> = {
    fontSize: 42,
    fill: '#1DBBAC',
    wordWrap: true,
    wordWrapWidth: 1136,
    align: 'center'
};

export class HowToPlaySlide extends Slide {
    public animation: Spine;

    private info: PIXI.Text;

    constructor(skeleton: SkeletonData, slideText: string) {
        super();
        this.animation = new Spine(skeleton);
        this.addChild(this.animation);

        this.info = new PIXI.Text(slideText, TEXT_STYLE);
        this.info.anchor.set(0.5, 0);
        this.addChild(this.info);

        this.animation.skeleton.setToSetupPose();
        this.animation.autoUpdate = true;
    }

    public play(): void {
        const trackEntry = this.animation.state.setAnimation(this.slideIndex, 'animation', false);
        trackEntry.listener = { complete: this.onAnimationComplete.bind(this) };
    }

    public handleOrientationChange(slideWidth: number, slideHeight: number, yPosition: number): void {
        super.handleOrientationChange(slideWidth, slideHeight, yPosition);

        this.info.style.wordWrapWidth = 1136;
        
        const upwardOffset = 30;
        this.animation.position.y = 0;
        this.info.position.y = (slideHeight * 0.5) - upwardOffset;
    }
}
